                n = 'This answer is correct. Ask for the last four digits of the phone number.'
            elif str(d.get('wrong_answers_left')) == '0':
                n = 'Three wrong answers. Say you cannot continue without verification, do not mention the account, and end with: Have a good day.'
            elif not t(d.get('ok')):
                n = 'The answer could not be read and was not counted. Ask the customer to say it again.'
            else:
                n = 'Wrong answer. Ask the same question once more. Do not say what was wrong.'
            if d.get('hint') == 'day_month_swapped':
