            d['what_to_do_next'] = n
except Exception:
    pass

try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict) and isinstance(d.get('products'), list):
            for p in d['products']:
                if not isinstance(p, dict):
                    continue
                t = p.get('type')
                if t == 'car_loan':
                    p['handling'] = 'No promise, no floor, no note. Transfer to queue restructuring.'
                    continue
                c = int(round(float(p.get('past_due') or 0) * 100))
                pct = 40 if t == 'credit_card' else 25
                p['floor'] = round(((c * pct + 50) // 100) / 100.0, 2)
                if int(p.get('days_late') or 0) <= 10:
                    p['band'] = 'early'
                    p['deadline'] = '2026-10-20 (Tuesday 20 October 2026)'
                    p['attempts'] = 1
                else:
                    p['band'] = 'late'
                    p['deadline'] = '2026-10-19 (Monday 19 October 2026)'
                    p['attempts'] = 2
            d['what_to_do_next'] = 'State every product in this order with its past_due, then ask once whether they can pay the full past_due of all non-car products today.'
        elif isinstance(d, dict):
            d['what_to_do_next'] = 'The account could not be loaded. Call get_account once more.'
except Exception:
    pass

try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            if str(d.get('ok')).lower() == 'true':
                d['what_to_do_next'] = 'Saved. Say exactly: A confirmation email will be sent to the address on file. Then go on with the next step.'
            else:
                d['what_to_do_next'] = 'Not saved. Call create_promise once more with the same values. If it fails again, say this promise could not be recorded.'
